    $labels = [];
    foreach ($field['value'] as $segment) {
        if (is_array($segment) && is_string($segment['label'] ?? null) && $segment['label'] !== '') { $labels[] = $segment['label']; }
    }
    return ra_repair_source_encoding(implode(' / ', $labels));
}
